"""fix_makefile_tabs_v2.py

Rewrite Makefile.tmpl with explicit tab escapes.
"""
from __future__ import annotations
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
MK = ROOT / "eclipse_installer" / "templates" / "Makefile.tmpl"

T = "\t"  # explicit tab

lines = [
    "# Makefile - StaTable Eclipse project (STM32F405)",
    "# Generated by StaTable Eclipse Installer v0.1.0",
    "",
    "PREFIX  = arm-none-eabi-",
    "CC      = $(PREFIX)gcc",
    "AS      = $(PREFIX)gcc -x assembler-with-cpp",
    "OBJCOPY = $(PREFIX)objcopy",
    "SIZE    = $(PREFIX)size",
    "",
    "TARGET  = firmware",
    "BUILD   = build",
    "",
    "C_SOURCES   := $(shell find . -path ./$(BUILD) -prune -o -name '*.c' -print)",
    "ASM_SOURCES := $(shell find . -path ./$(BUILD) -prune -o -name '*.s' -print)",
    "",
    "OBJECTS := $(addprefix $(BUILD)/,$(C_SOURCES:.c=.o))",
    "OBJECTS += $(addprefix $(BUILD)/,$(ASM_SOURCES:.s=.o))",
    "",
    "MCU     = -mcpu=cortex-m4 -mthumb",
    "INCLUDES = $(addprefix -I,$(shell find . -path ./$(BUILD) -prune -o -type d -print | grep -v '^\\.$$'))",
    "",
    "CFLAGS  = $(MCU) $(INCLUDES) -std=c99 -Wall -Wextra -ffunction-sections -fdata-sections -Og -g3",
    "ASFLAGS = $(MCU) $(INCLUDES) -g3",
    "LDFLAGS = $(MCU) -specs=nano.specs -specs=nosys.specs -Tlinker_stm32f405.ld -Wl,--gc-sections -Wl,-Map=$(BUILD)/$(TARGET).map",
    "LIBS    = -lc -lm",
    "",
    ".PHONY: all clean size",
    "",
    "all: $(BUILD)/$(TARGET).elf $(BUILD)/$(TARGET).bin size",
    "",
    "$(BUILD)/%.o: %.c",
    T + "@mkdir -p $(dir $@)",
    T + "$(CC) -c $(CFLAGS) $< -o $@",
    "",
    "$(BUILD)/%.o: %.s",
    T + "@mkdir -p $(dir $@)",
    T + "$(AS) -c $(ASFLAGS) $< -o $@",
    "",
    "$(BUILD)/$(TARGET).elf: $(OBJECTS)",
    T + "$(CC) $(OBJECTS) $(LDFLAGS) $(LIBS) -o $@",
    "",
    "$(BUILD)/$(TARGET).bin: $(BUILD)/$(TARGET).elf",
    T + "$(OBJCOPY) -O binary $< $@",
    "",
    "size: $(BUILD)/$(TARGET).elf",
    T + "$(SIZE) $<",
    "",
    "clean:",
    T + "rm -rf $(BUILD)",
    "",
]

MK.write_text("\n".join(lines), encoding="utf-8")
print(f"[OK] wrote {MK}")
print(f"[INFO] tab bytes: {MK.read_bytes().count(9)}")
